            state <= state_next;
            data_idx <= data_idx_next;
        end
        if (rst) begin
            state <= IDLE;
            data_idx <= 0;
        end
    end

    always_comb begin
        data_out = 1'b1;
        state_next = IDLE;
        data_idx_next = 0;

        case(state)
            IDLE: state_next = (tx_start) ? START : IDLE;
            STOP: state_next = IDLE;
            START: begin
                data_out = 0;
                state_next = DATA;
            end
